import React from "react";
import { createRoot } from "react-dom/client";

function ProductCard({ name, price }) {
  return (
    <article className="product-card">
      <h3>{name}</h3>
      <p className="price">₮ {price.toLocaleString("en-US")}</p>
      <button className="btn-add" data-testid="add-to-cart">Сагсанд хийх</button>
    </article>
  );
}

function App() {
  return (
    <main>
      <h1>Shop.mn</h1>
      <p>Монголын шилдэг онлайн дэлгүүр</p>
      <section className="product-grid">
        <ProductCard name="Монгол дээл" price={129000} />
        <ProductCard name="Малгай" price={45000} />
      </section>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);
